static bool getCountryFlagData(const char* cc, const uint16_t** outData, int* outW, int* outH) {
  for (int i = 0; i < kFlagTableSize; i++) {
    FlagEntry entry;
    memcpy_P(&entry, &kFlagTable[i], sizeof(FlagEntry));
    if (entry.cc[0] == cc[0] && entry.cc[1] == cc[1]) {
      *outW = pgm_read_word(&entry.data[0]);
      *outH = pgm_read_word(&entry.data[1]);
      *outData = &entry.data[2];
      return true;
    }
  }
  return false;
}
